// [photo, laptop framing, phone framing, phone fit, phone photo]
// [photo, laptop framing, phone framing]
const DEPT_IMG = { tables: ['tables', '30% 50%', '35% 50%'], trees: ['trees', '50% 50%', '45% 50%'], home: ['home', '50% 40%', '50% 50%'], rugs: ['rugs', '50% 50%', '50% 50%'], lamps: ['lamps', '70% 60%', '72% 50%'] };
const total = () => STORE.cats.reduce((s, c) => s + (c.n || 0), 0);
